    "tema": "Implantación",
    "subtema": "Hormonas placentarias / Producción placentaria de estrógenos",
    "module": "Semana 20 - Ginecología y Obstetricia",
    "pagina": "📖 Referencia: Williams Obstetricia, 26.ª edición, capítulo 5."
